from helpers import spec,decline
HARD='HARD CONSTRAINTS: no text, lettering, pseudo-inscription, glyphs, logo, border, frame or watermark; no extra heads, limbs or fingers; no design borrowed from any film, game, anime or comic; fully opaque covering where human skin would be nude; no explicit gore; no generic glow aura, neon outline or energy ribbons. One square image, native resolution at least 1024x1024.'
def make(s,name,anatomy,action,power,camera,light,surface,setting,mood,groups,req,variant,choices,aura):
 ids=lambda ns:[s+'-c'+str(n).zfill(2) for n in ns]
 g={k:ids(v) for k,v in groups.items()};r=[dict(kind=k,description=d,claim_ids=ids(n)) for k,d,n in req]
 prompt=f'ONE original square premium painterly cinematic Mitoloka illustration of {name}.\nANATOMY: {anatomy}\nMOMENT: {action}\nPOWER: {power}\nSCALE & CAMERA: {camera}\nLIGHT & WEATHER: {light}\nSURFACE: {surface}\nSETTING: {setting}\nMOOD: {mood}\n{HARD}'
 spec(s,g,r,prompt,variant,choices,aura)
